CREATE OR REPLACE FUNCTION public.create_my_company_location(p_company_id uuid, p_name text, p_address text, p_city text, p_phone text DEFAULT NULL::text, p_hours jsonb DEFAULT '{}'::jsonb, p_official_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_id uuid;
  v_role text;
begin
  if v_user is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select role into v_role
  from public.company_memberships
  where company_id = p_company_id
    and user_id = v_user
    and verification_status = 'verified'
    and role in ('owner','admin')
  limit 1;

  if v_role is null then
    raise exception 'verified_owner_or_admin_required' using errcode='42501';
  end if;

  if nullif(trim(coalesce(p_name,'')),'') is null
     or nullif(trim(coalesce(p_address,'')),'') is null
     or nullif(trim(coalesce(p_city,'')),'') is null then
    raise exception 'name_address_city_required' using errcode='22023';
  end if;

  insert into public.company_locations(
    company_id, name, relationship_type, canonical_address, city,
    phone, hours, official_url, source_url, status, verified_at
  )
  values(
    p_company_id, trim(p_name), 'owned', trim(p_address), trim(p_city),
    nullif(trim(coalesce(p_phone,'')),''),
    coalesce(p_hours,'{}'::jsonb),
    nullif(trim(coalesce(p_official_url,'')),''),
    'owner-submitted', 'published', now()
  )
  returning id into v_id;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(
    p_company_id, v_user, 'company_location.created', 'location', v_id,
    jsonb_build_object('role',v_role)
  );

  return jsonb_build_object('id',v_id,'company_id',p_company_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_company_service(p_company_id uuid, p_name text, p_category text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_official_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_user uuid:=auth.uid(); v_id uuid; v_role text;
begin
 if v_user is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select role into v_role from public.company_memberships where company_id=p_company_id and user_id=v_user and verification_status='verified' and role in ('owner','admin') limit 1;
 if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;
 if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'service_name_required' using errcode='22023'; end if;
 insert into public.company_services(company_id,name,category,description,official_url,source_url,status,verified_at)
 values(p_company_id,trim(p_name),nullif(trim(coalesce(p_category,'')),''),nullif(trim(coalesce(p_description,'')),''),nullif(trim(coalesce(p_official_url,'')),''),'owner-submitted','published',now()) returning id into v_id;
 insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata) values(p_company_id,v_user,'company_service.created','service',v_id,jsonb_build_object('role',v_role));
 return jsonb_build_object('id',v_id,'company_id',p_company_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_company_services(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_result jsonb;
begin
  if v_user is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select role into v_role from public.company_memberships
   where company_id=p_company_id and user_id=v_user
     and verification_status='verified' and role in ('owner','admin') limit 1;
  if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'name',s.name,'category',s.category,'description',s.description,
    'status',s.status,'created_at',s.created_at,'updated_at',s.updated_at
  ) order by s.created_at desc),'[]'::jsonb)
  into v_result
  from public.company_services s where s.company_id=p_company_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_my_company_location(p_company_id uuid, p_location_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_location public.company_locations%rowtype;
  v_next_status text;
begin
  if v_user is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select role into v_role
  from public.company_memberships
  where company_id=p_company_id
    and user_id=v_user
    and verification_status='verified'
    and role in ('owner','admin')
  limit 1;

  if v_role is null then
    raise exception 'verified_owner_or_admin_required' using errcode='42501';
  end if;

  select * into v_location
  from public.company_locations
  where id=p_location_id and company_id=p_company_id
  for update;

  if not found then
    raise exception 'company_location_not_found' using errcode='P0002';
  end if;

  if p_action='archive' then
    v_next_status := 'archived';
    update public.company_locations
      set status=v_next_status, updated_at=now()
      where id=p_location_id and company_id=p_company_id;
  elsif p_action='publish' then
    v_next_status := 'published';
    update public.company_locations
      set status=v_next_status, verified_at=now(), updated_at=now()
      where id=p_location_id and company_id=p_company_id;
  elsif p_action='delete' then
    v_next_status := 'deleted';
    delete from public.company_locations
      where id=p_location_id and company_id=p_company_id;
  else
    raise exception 'invalid_company_location_action' using errcode='22023';
  end if;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(
    p_company_id,
    v_user,
    'company_location.' || p_action,
    'location',
    p_location_id,
    jsonb_build_object(
      'role',v_role,
      'previous_status',v_location.status,
      'new_status',v_next_status,
      'name',v_location.name,
      'address',v_location.canonical_address
    )
  );

  return jsonb_build_object('id',p_location_id,'company_id',p_company_id,'status',v_next_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_my_company_service(p_company_id uuid, p_service_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_service public.company_services%rowtype;
  v_next_status text;
begin
  if v_user is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select role into v_role from public.company_memberships
   where company_id=p_company_id and user_id=v_user
     and verification_status='verified' and role in ('owner','admin') limit 1;
  if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;

  select * into v_service from public.company_services
   where id=p_service_id and company_id=p_company_id for update;
  if not found then raise exception 'company_service_not_found' using errcode='P0002'; end if;

  if p_action='archive' then
    v_next_status:='archived';
    update public.company_services set status=v_next_status,updated_at=now()
     where id=p_service_id and company_id=p_company_id;
  elsif p_action='publish' then
    v_next_status:='published';
    update public.company_services set status=v_next_status,verified_at=now(),updated_at=now()
     where id=p_service_id and company_id=p_company_id;
  elsif p_action='delete' then
    v_next_status:='deleted';
    delete from public.company_services where id=p_service_id and company_id=p_company_id;
  else
    raise exception 'invalid_company_service_action' using errcode='22023';
  end if;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(p_company_id,v_user,'company_service.'||p_action,'service',p_service_id,
    jsonb_build_object('role',v_role,'previous_status',v_service.status,
      'new_status',v_next_status,'name',v_service.name,'category',v_service.category));
  return jsonb_build_object('id',p_service_id,'company_id',p_company_id,'status',v_next_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.register_my_company_media(p_company_id uuid, p_storage_object_name text, p_media_type text, p_alt_text text DEFAULT NULL::text, p_caption text DEFAULT NULL::text, p_sort_order integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_media public.company_media%rowtype;
  v_expected_prefix text;
begin
  if v_uid is null then raise exception 'unauthorized' using errcode='42501'; end if;
  if p_media_type not in ('logo','cover','interior','exterior','products','team') then
    raise exception 'invalid_media_type' using errcode='22023';
  end if;
  if p_sort_order < 0 then raise exception 'invalid_sort_order' using errcode='22023'; end if;
  if not exists (
    select 1 from public.company_memberships cm
    where cm.company_id=p_company_id and cm.user_id=v_uid
      and cm.verification_status='verified' and cm.role in ('owner','admin')
  ) then raise exception 'forbidden' using errcode='42501'; end if;

  v_expected_prefix := p_company_id::text || '/' || p_media_type || '/';
  if p_storage_object_name is null or length(p_storage_object_name)>1024
     or p_storage_object_name not like v_expected_prefix || '%'
     or p_storage_object_name like '%..%' or p_storage_object_name like '%\\%'
  then raise exception 'invalid_storage_object_name' using errcode='22023'; end if;

  if not exists (
    select 1 from storage.objects so
    where so.bucket_id='company-media' and so.name=p_storage_object_name
  ) then raise exception 'storage_object_not_found' using errcode='P0002'; end if;

  update public.company_media
     set status='archived', updated_at=now()
   where company_id=p_company_id and media_type=p_media_type
     and status='published' and storage_object_name<>p_storage_object_name;

  insert into public.company_media(
    company_id,storage_object_name,media_type,status,sort_order,alt_text,caption,updated_at
  ) values (
    p_company_id,p_storage_object_name,p_media_type,'published',p_sort_order,
    nullif(btrim(p_alt_text),''),nullif(btrim(p_caption),''),now()
  )
  on conflict (company_id,storage_object_name)
  do update set media_type=excluded.media_type,status='published',
    sort_order=excluded.sort_order,alt_text=excluded.alt_text,
    caption=excluded.caption,updated_at=now()
  returning * into v_media;

  return jsonb_build_object(
    'id',v_media.id,'company_id',v_media.company_id,
    'object_name',v_media.storage_object_name,'type',v_media.media_type,
    'status',v_media.status,'sort_order',v_media.sort_order,
    'alt',v_media.alt_text,'caption',v_media.caption,'updated_at',v_media.updated_at
  );
end;
$function$
